const body = $json.body || $json;
const provider = body.provider || $env.WHATSAPP_PROVIDER || 'generic';
const rawMessage = body.message || body.messages?.[0] || body.entry?.[0]?.changes?.[0]?.value?.messages?.[0] || body;
const contact = body.contact || body.contacts?.[0] || body.entry?.[0]?.changes?.[0]?.value?.contacts?.[0] || {};
const phone = rawMessage.from || body.phone || contact.wa_id || body.sender || '';
const name = contact.profile?.name || body.name || null;
const messageType = rawMessage.type || body.message_type || (rawMessage.text || body.text ? 'text' : 'unknown');
const text = rawMessage.text?.body || rawMessage.text || body.text || body.caption || '';
const media = rawMessage.audio || rawMessage.video || rawMessage.image || body.media || null;
return [{ json: { provider, phone, name, message_type: messageType, text, media, raw: body } }];

const item = $json;
const content = item.text || item.media?.caption || '';
const lower = content.toLowerCase();
const attrs = {
  neighborhood: lower.includes('alto do ipiranga') ? 'Alto do Ipiranga' : null,
  street: lower.includes('rui barbosa') ? 'Rua Rui Barbosa' : lower.includes('bento vieira') ? 'Rua Bento Vieira' : null,
  property_type: lower.includes('sobrado') ? 'sobrado' : lower.includes('apartamento') ? 'apartamento' : lower.includes('casa') ? 'casa' : null,
  bedrooms: /3|tres|três/.test(lower) && /dorm/.test(lower) ? 3 : null,
  parking_spaces: /2|duas|dois/.test(lower) && /(vaga|garagem|carro)/.test(lower) ? 2 : null,
  visual: lower.includes('portao azul') || lower.includes('portão azul') ? 'portao azul' : null,
  wants_broker: lower.includes('corretor'),
  wants_visit: /(visita|sábado|sabado|domingo|horário|horario|agendar)/.test(lower)
};
const intent = attrs.wants_broker ? 'handoff' : attrs.wants_visit ? 'schedule_visit' : 'property_search';
return [{ json: { ...item, normalized_text: content, intent, attrs } }];

const candidates = Array.isArray($json) ? $json : ($json.data || $json.body || []);
const previous = $items('Extract Intent and Attributes')[0].json;
let reply;
if (previous.intent === 'handoff') {
  reply = 'Claro, posso te colocar em contato com um corretor. Enquanto isso, ja posso tentar deixar uma visita pre-agendada para o senhor. Tenho sabado pela manha ou domingo as 14h. Qual funciona melhor?';
} else if (!candidates.length) {
  reply = 'Entendi o que voce procura. Para eu localizar sem inventar, voce lembra alguma pista objetiva: rua, bairro, dormitorios, garagem, cor do portao, faixa de preco ou referencia do site?';
} else if (candidates.length > 1 && candidates[0].total_score < 6) {
  const opts = candidates.slice(0, 3).map((p) => `${p.street || p.neighborhood}, ${p.bedrooms || '?'} dorms, ${p.parking_spaces || 0} vagas`).join('; ');
  reply = `Encontrei algumas opcoes parecidas: ${opts}. O senhor lembra se era alguma dessas ruas ou algum detalhe da fachada?`;
} else {
  const p = candidates[0];
  reply = `Pelo que voce descreveu, parece ser ${p.title}. Ele tem ${p.bedrooms || '?'} dormitorios, ${p.parking_spaces || 0} vagas e fica em ${p.street || p.neighborhood}. Quer que eu ja veja uma visita? Tenho sabado pela manha ou domingo as 14h.`;
}
return [{ json: { ...previous, candidates, reply } }];
